import Foundation
import CoreGraphics

@main
struct ClockModelTests {
    @MainActor static func main() {
        var checks = 0
        func expect(_ condition: @autoclosure () -> Bool, _ message: String) {
            checks += 1
            if !condition() { fatalError("FAILED: \(message)") }
        }
        func snapshot(_ zone: String, at value: String, local: String = "America/New_York") -> ClockSnapshot {
            ClockSnapshot(region: ClockRegion(id: zone), instant: ISO8601DateFormatter().date(from: value)!,
                local: TimeZone(identifier: local)!, language: .simplifiedChinese)
        }

        let fixture = "2026-10-16T20:42:00Z"
        let london = snapshot("Europe/London", at: fixture)
        let shanghai = snapshot("Asia/Shanghai", at: fixture)
        let tokyo = snapshot("Asia/Tokyo", at: fixture)
        expect(london.time == "21:42" && london.date == "2026/10/16", "London time and full date")
        expect(london.weekday == "周五" && london.differenceLabel == "快 5 小时", "London weekday and DST offset")
        expect(shanghai.time == "04:42" && shanghai.date == "2026/10/17", "Shanghai next day date")
        expect(shanghai.dayLabel == "次日" && shanghai.weekday == "周六", "Next day badge and weekday")
        expect(tokyo.time == "05:42" && tokyo.differenceLabel == "快 13 小时", "Tokyo synchronized time")
        let secondsNY = snapshot("America/New_York", at: "2026-10-16T23:44:36Z")
        let secondsShanghai = snapshot("Asia/Shanghai", at: "2026-10-16T23:44:36Z")
        expect(secondsNY.second == 36 && secondsShanghai.second == 36, "Seconds stay synchronized across regions")
        expect(secondsNY.time == "19:44" && secondsNY.timeWithSeconds == "19:44:36", "Primary time stays HH:mm and accessibility exposes seconds")
        expect(snapshot("Asia/Kathmandu", at: "2026-10-16T23:44:09Z").secondLabel == "09", "Fractional-offset regions retain zero-padded seconds")
        let lastSecond = snapshot("Asia/Shanghai", at: "2026-10-16T15:59:59Z")
        let firstSecond = snapshot("Asia/Shanghai", at: "2026-10-16T16:00:00Z")
        expect(lastSecond.second == 59 && firstSecond.second == 0 && firstSecond.secondLabel == "00", "Seconds orbit resets at the minute boundary")
        expect(lastSecond.time == "23:59" && firstSecond.time == "00:00" && firstSecond.date == "2026/10/17", "Seconds rollover updates time and full date together at midnight")
        let fractionalInstant = ISO8601DateFormatter().date(from: "2026-10-16T23:44:59Z")!.addingTimeInterval(0.999)
        let fractionalSnapshot = ClockSnapshot(region: .local, instant: fractionalInstant, local: TimeZone(identifier: "America/New_York")!)
        expect(fractionalSnapshot.second == 59, "Subsecond time is never rounded into the next minute early")
        let local = ClockSnapshot(region: .local, instant: ISO8601DateFormatter().date(from: fixture)!, local: TimeZone(identifier: "America/New_York")!, language: .simplifiedChinese)
        expect(local.time == "16:42" && local.isLocal && local.offsetLabel == "UTC−4", "System local clock")

        let before = snapshot("America/New_York", at: "2026-11-01T05:30:00Z", local: "Etc/UTC")
        let after = snapshot("America/New_York", at: "2026-11-01T06:30:00Z", local: "Etc/UTC")
        expect(before.time == "01:30" && after.time == "01:30", "Fall DST repeated hour")
        expect(before.offsetLabel == "UTC−4" && after.offsetLabel == "UTC−5", "Fall DST offset change")
        let springBefore = snapshot("America/New_York", at: "2026-03-08T06:59:00Z", local: "Etc/UTC")
        let springAfter = snapshot("America/New_York", at: "2026-03-08T07:00:00Z", local: "Etc/UTC")
        expect(springBefore.time == "01:59" && springAfter.time == "03:00", "Spring DST skipped hour")
        expect(snapshot("Europe/London", at: "2026-10-28T12:00:00Z").differenceLabel == "快 4 小时", "Different DST transition dates")

        let nepal = snapshot("Asia/Kathmandu", at: fixture, local: "Etc/UTC")
        expect(nepal.offsetLabel == "UTC+5:45" && nepal.differenceLabel == "快 5 小时 45 分钟", "Quarter hour timezone")
        let india = snapshot("Asia/Kolkata", at: fixture, local: "Etc/UTC")
        expect(india.time == "02:12" && india.differenceLabel == "快 5 小时 30 分钟", "Half hour timezone with rollover")
        let previous = snapshot("America/Los_Angeles", at: "2026-10-16T02:00:00Z", local: "Asia/Tokyo")
        expect(previous.date == "2026/10/15" && previous.dayLabel == "前日", "Previous day")
        let dateline = snapshot("Pacific/Kiritimati", at: "2026-10-16T10:30:00Z", local: "Pacific/Pago_Pago")
        expect(dateline.dayDifference == 2 && dateline.dayLabel == "+2 天", "International date line two day difference")
        let newYear = snapshot("Asia/Tokyo", at: "2026-12-31T20:00:00Z")
        expect(newYear.date == "2027/01/01" && newYear.weekday == "周五", "New year date with calendar year")
        let leapDay = snapshot("Asia/Shanghai", at: "2028-02-28T20:00:00Z")
        expect(leapDay.date == "2028/02/29", "Leap year date")
        let same = snapshot("Europe/Paris", at: fixture, local: "Europe/Berlin")
        expect(same.differenceLabel == "与本地同一时间", "Equal UTC offsets")
        let defaults = CityCatalog.defaults(local: TimeZone(identifier: "Asia/Tokyo")!)
        expect(defaults.count == 4 && !defaults.dropFirst().contains { $0.id == "Asia/Tokyo" }, "Four defaults without duplicated local zone")
        expect(CityCatalog.search("东京").contains("Asia/Tokyo"), "Chinese city search")
        expect(CityCatalog.search("London").contains("Europe/London"), "English city search")
        expect(CityCatalog.search("no-such-city-123").isEmpty, "Search empty state")
        let worldwide = CityCatalog.search("")
        expect(worldwide.count > 400 && Set(worldwide).count == worldwide.count, "Worldwide directory, rather than just favorites")
        expect(worldwide.allSatisfy { TimeZone(identifier: $0) != nil }, "Every selectable region is supported by the system")
        expect(CityCatalog.search("巴西").contains("America/Sao_Paulo") && CityCatalog.search("Brazil").contains("America/Sao_Paulo"), "Chinese and English country search")
        expect(CityCatalog.search("阿克拉").contains("Africa/Accra") && CityCatalog.search("温得和克").contains("Africa/Windhoek"), "CLDR names for cities outside the old catalog")
        expect(CityCatalog.search("Calcutta") == ["Asia/Kolkata"], "Legacy names resolve to one selectable region")
        expect(!CityCatalog.defaults(local: TimeZone(identifier: "Japan")!).dropFirst().contains { $0.id == "Asia/Tokyo" }, "Legacy local zone names do not duplicate default clocks")
        expect(worldwide.contains("Europe/Stockholm") && worldwide.contains("Europe/Berlin"), "Distinct cities remain selectable when their clock rules are linked")
        expect(CityCatalog.search("London", area: .asia).isEmpty && CityCatalog.search("Tokyo", area: .asia) == ["Asia/Tokyo"], "Region filters apply to search")
        expect(CityCatalog.search("Sao Paulo").contains("America/Sao_Paulo"), "Search ignores separators and accents")
        expect(CityCatalog.search("Etc/UTC").contains("Etc/UTC"), "UTC is explicitly selectable")
        expect(CityCatalog.search("USA").contains("America/Los_Angeles") && CityCatalog.search("非洲").contains("Africa/Accra"), "Common country aliases and translated geographical areas")
        for area in [WorldArea.asia, .europe, .americas, .africa, .oceania, .antarctica, .atlantic, .indian] {
            expect(!CityCatalog.search("", area: area).isEmpty, "Worldwide area coverage: \(area.rawValue)")
        }
        let grouped = CityCatalog.sections(for: worldwide, showPopular: true).flatMap(\.identifiers)
        expect(Set(grouped) == Set(worldwide) && grouped.count == worldwide.count, "Browse groups neither hide nor duplicate regions")
        expect(WorldRegionData.places.values.allSatisfy { (-90...90).contains($0.latitude) && (-180...180).contains($0.longitude) }, "Representative weather coordinates are in range")
        let buenosAires = CityCatalog.location(for: "America/Argentina/Buenos_Aires")!
        expect(abs(buenosAires.latitude + 34.6) < 0.01 && abs(buenosAires.longitude + 58.45) < 0.01, "Southern and western coordinates retain their signs")
        print("Worldwide directory: \(worldwide.count) selectable regions.")
        let weatherData = Data(#"{"current":{"time":1792183320,"temperature_2m":-3.6,"weather_code":73,"is_day":0}}"#.utf8)
        let now = Date(timeIntervalSince1970: 1792183500)
        let weather = try! WeatherClient.decode(weatherData, fetchedAt: now)
        expect(weather.temperatureLabel == "-4°C" && weather.condition == "雪", "Negative temperatures and WMO snow")
        expect(!weather.isDay && weather.symbol == "cloud.snow", "Weather icons use actual weather")
        expect(!weather.isStale(at: now) && weather.isStale(at: now.addingTimeInterval(1801)), "Cached weather expires")
        let clearNight = WeatherReading(temperature: 0, code: 0, isDay: false, observedAt: now, fetchedAt: now)
        expect(clearNight.symbol == "moon.stars" && clearNight.condition == "晴", "Clear night weather differs from daylight")
        let thunder = WeatherReading(temperature: 20, code: 99, isDay: true, observedAt: now, fetchedAt: now)
        expect(thunder.condition == "雷雨", "WMO thunderstorm and hail")
        expect((try? WeatherClient.decode(Data(#"{"current":{"time":1792183320,"temperature_2m":null,"weather_code":0,"is_day":1}}"#.utf8))) == nil, "Missing temperature is unavailable, never zero degrees")
        expect((try? WeatherClient.decode(Data(#"{"error":true,"reason":"rate limit"}"#.utf8))) == nil, "Service errors never become weather")
        expect(WeatherClient.cityQuery(for: "Etc/UTC") == nil && WeatherClient.cityQuery(for: "UTC") == nil, "UTC has no invented city weather")
        expect(WeatherClient.cityQuery(for: "America/Argentina/Buenos_Aires") == "Buenos Aires", "Weather search uses final city component")
        expect(WeatherClient.coordinates["Asia/Kolkata"]?.latitude == 28.61, "Weather coordinates match displayed New Delhi city")
        let english = ClockSnapshot(region: ClockRegion(id: "Asia/Shanghai"), instant: ISO8601DateFormatter().date(from: fixture)!, local: TimeZone(identifier: "America/New_York")!)
        expect(english.city == "Shanghai" && english.weekday == "Sat" && english.dayLabel == "Next day", "English is the default language")
        expect(english.date == "2026/10/17" && english.differenceLabel == "+12h", "English retains complete date and accurate offset")
        expect(CityCatalog.name(for: "Asia/Kolkata") == "New Delhi", "English weather city matches New Delhi")
        expect(AppLanguage.english.text("管理地区") == "Manage clocks", "English UI translation")
        expect(AppLanguage.simplifiedChinese.text("管理地区") == "管理地区", "Chinese UI translation")
        expect(weather.condition(in: .english) == "Snow", "Localized weather")
        let key = Data(repeating: 1, count: 32).base64EncodedString()
        expect(UpdateConfiguration(feed: "https://example.com/appcast.xml", publicKey: key).isConfigured, "HTTPS signed update configuration")
        expect(!UpdateConfiguration(feed: "http://example.com/appcast.xml", publicKey: key).isConfigured, "Reject insecure update feeds")
        expect(!UpdateConfiguration(feed: "https://example.com/appcast.xml", publicKey: "invalid").isConfigured, "Reject missing or invalid update signatures")
        expect(!UpdateConfiguration(feed: nil, publicKey: nil).isConfigured, "Unconfigured updater remains inactive")
        let screen = CGRect(x: 0, y: 0, width: 1440, height: 875)
        let dropdown = DropdownGeometry.frame(anchor: CGRect(x: 1320, y: 875, width: 110, height: 25), visibleFrame: screen, size: CGSize(width: 286, height: 450))
        expect(dropdown.maxY == 867 && dropdown.maxX <= 1432, "Menu bar dropdown has top and right margins")
        let short = DropdownGeometry.frame(anchor: CGRect(x: 500, y: 300, width: 30, height: 25), visibleFrame: CGRect(x: 0, y: 0, width: 800, height: 500), size: CGSize(width: 286, height: 650))
        expect(short.minY >= 8 && short.maxY <= 492 && short.height == 484, "Dropdown fits short screens without clipping")
        let second = DropdownGeometry.frame(anchor: CGRect(x: -100, y: 900, width: 80, height: 25), visibleFrame: CGRect(x: -1440, y: 100, width: 1440, height: 800), size: CGSize(width: 286, height: 450))
        expect(second.minX >= -1432 && second.maxX <= -8 && second.maxY <= 892, "Dropdown handles negative-coordinate monitors")
        let widget = CGSize(width: 360, height: 210)
        let nearTopRight = CGRect(origin: CGPoint(x: 1050, y: 632), size: widget)
        expect(DesktopGeometry.origin(for: nearTopRight, in: screen, snap: true) == CGPoint(x: 1064, y: 649), "Desktop panel snaps to both edges at a corner")
        expect(DesktopGeometry.origin(for: nearTopRight, in: screen, snap: false) == nearTopRight.origin, "Disabling snapping preserves an in-bounds position")
        let middle = CGRect(origin: CGPoint(x: 450, y: 350), size: widget)
        expect(DesktopGeometry.origin(for: middle, in: screen, snap: true) == middle.origin, "Dragging in the middle does not move the panel to an edge")
        let offscreen = CGRect(origin: CGPoint(x: 1500, y: -400), size: widget)
        expect(DesktopGeometry.origin(for: offscreen, in: screen, snap: false) == CGPoint(x: 1064, y: 16), "Offscreen panels are recoverable inside the visible screen")
        let leftScreen = CGRect(x: -1440, y: 100, width: 1440, height: 800)
        let leftPanel = CGRect(origin: CGPoint(x: -1420, y: 130), size: widget)
        expect(DesktopGeometry.origin(for: leftPanel, in: leftScreen, snap: true) == CGPoint(x: -1424, y: 116), "Desktop snapping supports a monitor left of the primary display")
        expect(DesktopGeometry.screen(for: leftPanel, in: [screen, leftScreen]) == leftScreen, "Dragging selects the screen containing most of the panel")
        expect(DesktopGeometry.screen(for: CGRect(x: -2200, y: 150, width: 360, height: 210), in: [screen, leftScreen]) == leftScreen, "Disconnected displays recover onto the nearest screen")
        expect(DesktopGeometry.screen(for: middle, in: []) == nil, "No screen is handled safely")
        let horizontal = DesktopLayoutMetrics(layout: .horizontal, clockCount: 4, availableSize: screen.size)
        expect(horizontal.columns == 4 && horizontal.size == CGSize(width: 720, height: 210), "Horizontal layout preserves the existing compact panel")
        let vertical = DesktopLayoutMetrics(layout: .vertical, clockCount: 4, availableSize: screen.size)
        expect(vertical.columns == 1 && vertical.size == CGSize(width: 220, height: 732), "Vertical layout stacks complete clock cards")
        let independent = DesktopLayoutMetrics(layout: .independent, clockCount: 4, availableSize: screen.size)
        expect(independent.size == CGSize(width: 220, height: 210) && independent.rows == 1, "Independent clocks retain the full date and seconds card")
        let tall = DesktopLayoutMetrics(layout: .vertical, clockCount: 6, availableSize: screen.size)
        expect(tall.needsScrolling && tall.size.height == screen.height - 32 && tall.contentHeight == 1044, "Tall stacks scroll inside the screen instead of clipping clocks")
        let narrow = DesktopLayoutMetrics(layout: .horizontal, clockCount: 6, availableSize: CGSize(width: 640, height: 480))
        expect(narrow.columns == 3 && narrow.rows == 2 && narrow.size.width == 540, "Horizontal clocks wrap on narrow monitors")
        expect(DesktopLayoutMetrics(layout: .independent, clockCount: 0, availableSize: screen.size).size == CGSize(width: 360, height: 110), "An empty independent layout keeps an accessible add-clock panel")
        let ids = ["system", "Asia/Shanghai"]
        expect(DesktopLayout.independent.panelIDs(for: ids) == ids && DesktopLayout.vertical.panelIDs(for: ids) == ["combined"], "Independent mode creates one stable window per selected clock")
        expect(DesktopLayout.independent.panelIDs(for: []) == ["combined"], "Removing the last desktop clock does not lose the controls")
        expect(DesktopLayout.horizontal.positionKey(for: "combined") != DesktopLayout.vertical.positionKey(for: "combined"), "Each combined layout remembers its own position")
        expect(DesktopLayout.independent.positionKey(for: "system") == "clock:system", "An independent clock keeps its position when reordered or renamed")
        let suite = "MeridianLayoutTests." + UUID().uuidString
        let layoutDefaults = UserDefaults(suiteName: suite)!
        defer { layoutDefaults.removePersistentDomain(forName: suite) }
        let layoutStore = ClockStore(fixedInstant: now, localZone: TimeZone(identifier: "America/New_York")!, defaults: layoutDefaults)
        expect(layoutStore.desktopLayout == .horizontal, "Existing users migrate to the horizontal layout")
        layoutStore.desktopRegionIDs = Set(ids)
        layoutStore.desktopLayout = .independent
        layoutStore.closeDesktopPanel("system")
        expect(!layoutStore.panelVisible("system") && layoutStore.panelVisible("Asia/Shanghai"), "Closing one independent clock leaves the others visible")
        expect(layoutStore.desktopRegionIDs == Set(ids), "Closing a clock keeps its selected region")
        layoutStore.closeDesktopPanel("Asia/Shanghai")
        expect(!layoutStore.desktopVisible, "Closing the last clock minimizes all clocks to the menu bar")
        layoutStore.revealDesktop()
        expect(layoutStore.panelVisible("system") && layoutStore.panelVisible("Asia/Shanghai") && layoutStore.dismissedDesktopIDs.isEmpty, "Open always restores every selected desktop clock")
        layoutStore.closeDesktopPanel("system")
        let restoredStore = ClockStore(fixedInstant: now, defaults: layoutDefaults)
        expect(restoredStore.desktopLayout == .independent && !restoredStore.panelVisible("system") && restoredStore.panelVisible("Asia/Shanghai"), "Arrangement and independently closed clocks survive a restart")
        layoutStore.desktopLayout = .vertical
        expect(layoutStore.dismissedDesktopIDs.isEmpty && layoutStore.panelVisible("combined"), "Combining clocks restores the complete stack")
        layoutStore.closeDesktopPanel("combined")
        expect(!layoutStore.desktopVisible, "Closing a combined panel minimizes it to the menu bar")
        layoutDefaults.set("unknown-layout", forKey: "desktopLayout")
        expect(ClockStore(fixedInstant: now, defaults: layoutDefaults).desktopLayout == .horizontal, "An unrecognized saved arrangement recovers safely")
        expect(AppLanguage.english.text("独立时钟") == "Independent clocks" && AppLanguage.english.text("纵向排列") == "Vertical", "New layout controls are localized in English")
        print("Passed \(checks) checks: full dates, DST, fractional offsets, city search, weather decoding, cache freshness and desktop layout lifecycle.")
    }
}
